 "content": "def transform(grid):
    """Continue the periodic foreground motif at the right edge, marking new cells 1."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    fg = next((v for row in grid for v in row if v != bg), None)
    if fg is None:
        return out

    # Find patterned rows with a long solid run followed by a short, repeating
    # tail. Extrapolate the observed tail motif only into the trailing background.
    for r, row in enumerate(grid):
        last = max((c for c, v in enumerate(row) if v != bg), default=-1)
        if last < 0 or last == len(row) - 1:
            continue
        runs = []
        c = 0
        while c <= last:
            if row[c] == fg:
                e = c
                while e + 1 <= last and row[e + 1] == fg:
                    e += 1
                if e - c + 1 >= 4:
                    runs.append((c, e))
                c = e + 1
            else:
                c += 1
        if not runs:
            continue
        _, end = runs[-1]
        tail_start = max(end + 1, last - 3)
        tail = row[tail_start:last + 1]
        period = None
        for p in range(1, min(6, len(tail)) + 1):
            if all(tail[i] == tail[i % p] for i in range(len(tail))):
                period = p
                break
        if period is None:
            continue
        motif = tail[:period]
        for c in range(last + 1, len(row)):
            if motif[(c - tail_start) % period] == fg:
                out[r][c] = 1
    return out

